"""Write decisions.json, the list behind Cory's decision board (the Curio Class Decisions artifact).

    python docs/agents/decisions/make_decisions.py

Each decision: id, area, tool, q (the question), rec (the recommendation, leaning toward what makes the site more
useful to teachers and students), why, blocks (what waits on it). Cory's answers live in the artifact's db
(`answers/<id>`: choice rec | other | hold, note, at), never here. To add questions (wave 4, later waves), append rows
and republish decisions.json to the same artifact; ids already answered must not change.
"""
import json
from pathlib import Path

D = []


def add(area, prefix, rows, blocks):
    for n, (tool, q, rec, why) in enumerate(rows, 1):
        D.append({'id': f'{prefix}-{n:02d}', 'area': area, 'tool': tool, 'q': q, 'rec': rec, 'why': why,
                  'blocks': blocks})


